cagri = 0
def fib(n):
    global cagri; cagri += 1
    return n if n < 2 else fib(n - 1) + fib(n - 2)
fib(20); print(cagri)

def fib(n, memo):
    if n in memo: return memo[n]
    if n < 2: return n
    return fib(n - 1, memo) + fib(n - 2, memo)

