def vezir(n):
    sut = []
    def uygun(r, k):
        return all(k != c and abs(k - c) != r - rr for rr, c in enumerate(sut))
    def git(r):
        if r == n: return 1
        t = 0
        for k in range(n):
            if uygun(r, k):
                sut.append(k); t += git(r + 1); sut.pop()
        return t
    return git(0)
print(vezir(6))
